import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Create gradient + grain texture
  const width = 512;
  const height = 512;
  const data = new Uint8Array(width * height * 4);

  const c0 = { r: 0x0b, g: 0x0b, b: 0x10 };
  const c1 = { r: 0x14, g: 0x14, b: 0x1a };

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      const t = y / height;

      const r = Math.round(c0.r + (c1.r - c0.r) * t);
      const g = Math.round(c0.g + (c1.g - c0.g) * t);
      const b = Math.round(c0.b + (c1.b - c0.b) * t);

      const noise = (Math.random() - 0.5) * 255 * 0.015;

      data[idx] = Math.max(0, Math.min(255, r + noise));
      data[idx + 1] = Math.max(0, Math.min(255, g + noise));
      data[idx + 2] = Math.max(0, Math.min(255, b + noise));
      data[idx + 3] = 255;
    }
  }

  const bgTexture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
  bgTexture.colorSpace = THREE.SRGBColorSpace;
  bgTexture.needsUpdate = true;
  disposables.push(bgTexture);

  // Background plane
  const bgGeom = new THREE.PlaneGeometry(7, 5.5);
  const bgMat = new THREE.MeshBasicNodeMaterial({ map: bgTexture });
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  group.add(bgMesh);
  disposables.push(bgGeom, bgMat);

  // Text specifications
  const textSpecs = [
    { text: 'NOVA ATELIER / JOURNAL', family: 'JetBrains Mono', size: 18, weight: 700, spacing: 0.12, y: 1.7, isHero: false },
    { text: 'PRECISION IS', family: 'Lora', size: 124, weight: 600, spacing: -0.015, y: 0.9, isHero: true },
    { text: 'A HABIT.', family: 'Lora', size: 124, weight: 600, spacing: -0.015, y: 0.25, isHero: true },
    { text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.', family: 'JetBrains Mono', size: 26, weight: 400, spacing: 0, y: -0.8, isHero: false },
    { text: 'ISSUE 12 / JULY 2026', family: 'JetBrains Mono', size: 18, weight: 400, spacing: 0.08, y: -1.9, isHero: false }
  ];

  const textItems = [];

  textSpecs.forEach((spec) => {
    const result = ctx.fontAtlas.createText(spec.text, {
      fontFamily: spec.family,
      fontSize: spec.size,
      fontWeight: spec.weight,
      letterSpacing: spec.spacing

    });

    if (result) {
      const mat = new THREE.MeshBasicNodeMaterial({
        color: new THREE.Color(0xe8ecf2),
        map: result.material?.map,
        transparent: true
      });

      const mesh = new THREE.Mesh(result.geometry, mat);
      mesh.position.set(-3.1, spec.y, 0.01);
      group.add(mesh);

      textItems.push({ mesh, spec });
      disposables.push(result.geometry, mat);

      // Letterpress shadow for hero text
      if (spec.isHero) {
        const shadowMat = new THREE.MeshBasicNodeMaterial({
          color: new THREE.Color(0x16161d),
          map: result.material?.map,
          transparent: true
        });

        const shadowMesh = new THREE.Mesh(result.geometry, shadowMat);
        shadowMesh.position.set(-3.1, spec.y, -0.02);
        group.add(shadowMesh);

        disposables.push(shadowMat);
      }
    }
  });

  // Accent underline rule
  const ruleGeom = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMat = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(0xff2a38),
    emissive: new THREE.Color(0xff2a38),
    emissiveIntensity: 1.2
  });

  const ruleMesh = new THREE.Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-3.1 + 1.1, -0.15, 0.02);
  ruleMesh.scale.x = 0;
  group.add(ruleMesh);

  disposables.push(ruleGeom, ruleMat);

  // Entrance animation
  const tl = gsap.timeline();

  textItems.forEach((item, i) => {
    const delay = i * 0.08;
    item.mesh.position.y += 0.4;
    item.mesh.material.opacity = 0;

    tl.to(
      item.mesh.position,
      { y: item.spec.y, duration: 0.7, ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' },
      delay
    );

    tl.to(
      item.mesh.material,
      { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' },
      delay
    );
  });

  // Rule animation (draws after hero lands)
  const ruleDelay = 0.7 + 0.08;
  tl.to(
    ruleMesh.scale,
    { x: 1, duration: 0.5, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' },
    ruleDelay
  );

  timelines.push(tl);

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    disposables.forEach(d => d?.dispose?.());
  };

  return group;
}
